options=read('/input/options')
from itertools import combinations
ids=[o['id'] for o in options]
result=None
for k in range(goal['min_count'],goal['max_count']+1):
 for combo in combinations(ids,k):
  sel=list(combo)
  # Check requires closure
  valid_requires=True
  selected_set=set(sel)
  for oid in sel:
   rec=[o for o in options if o['id']==oid][0]
   for r in rec['requires']:
    if r not in selected_set:
     valid_requires=False
     break
   if not valid_requires:
    break
  if not valid_requires:
   continue
  # Check conflicts if no_conflicts is True
  if goal['no_conflicts']:
   conflict_found=False
   for i in range(len(sel)):
    for j in range(i+1,len(sel)):
     rec_i=[o for o in options if o['id']==sel[i]][0]
     if sel[j] in rec_i['conflicts']:
      conflict_found=True
      break
    if conflict_found:
     break
   if conflict_found:
    continue
  # Check sum_bounds cost max
  total_cost=sum([o['cost'] for o in options if o['id'] in sel])
  if 'cost' in goal['sum_bounds'] and 'max' in goal['sum_bounds']['cost']:
   if total_cost>goal['sum_bounds']['cost']['max']:
    continue
  # Check cover tags
  tags_covered=[]
  for o in options:
   if o['id'] in sel:
    tags_covered+=o['tags']
  tags_covered_set=set(tags_covered)
  cover_tags=set(goal['cover']['tags'])
  if not cover_tags.issubset(tags_covered_set):
   continue
  # Check unique fields
  unique_fields=goal['unique']
  unique_ok=True
  for uf in unique_fields:
   vals=[o[uf] for o in options if o['id'] in sel]
   if len(vals)!=len(set(vals)):
    unique_ok=False
    break
  if not unique_ok:
   continue
  # Check order_by ascending lexicographic
  order_by=goal['order_by']
  if order_by:
   for i in range(len(sel)-1):
    a=[o for o in options if o['id']==sel[i]][0]
    b=[o for o in options if o['id']==sel[i+1]][0]
    for key in order_by:
     if a[key]>b[key]:
      break
    else:
     continue
    break
   else:
    pass
   # If break happened, continue outer
    if i<len(sel)-2:
     continue
  # Check valid
  if valid(sel):
   result=sel
   break
 if result is not None:
  break
if result is None:
 result=[]

